            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(12.dp)
        ) {
            Box(
                modifier = Modifier
                    .size(12.dp)
                    .clip(CircleShape)
                    .background(statusColor(status))
            )
            Column {
                Text(
                    text = status.name,
                    style = MaterialTheme.typography.labelLarge
                )
                if (status == StreamStatus.ONLINE) {
                    Text(
                        text = formatDuration(duration),
                        style = MaterialTheme.typography.bodySmall
                    )
                }
            }
        }
    }
}

@Composable
private fun ControlBar(
    streamStatus: StreamStatus,
    isMuted: Boolean,
    isFrontCamera: Boolean,
    onIntent: (MainStreamIntent) -> Unit,
    modifier: Modifier = Modifier
) {
    val isLive = streamStatus == StreamStatus.ONLINE || streamStatus == StreamStatus.CONNECTING
    val fabColor by animateColorAsState(
        targetValue = if (isLive) MaterialTheme.colorScheme.error else MaterialTheme.colorScheme.primary,
        animationSpec = tween(300),
        label = "fabColor"
    )

    Row(
        modifier = modifier
            .fillMaxWidth()
            .padding(horizontal = 24.dp),
        horizontalArrangement = Arrangement.SpaceEvenly,
        verticalAlignment = Alignment.CenterVertically
    ) {
        IconButton(
            onClick = { onIntent(MainStreamIntent.ToggleMicrophone) },
            modifier = Modifier
                .clip(CircleShape)
                .background(MaterialTheme.colorScheme.surface.copy(alpha = 0.85f))
        ) {
            Crossfade(
                targetState = isMuted,
                animationSpec = tween(200),
                label = "mic"
            ) { muted ->
                Icon(
                    imageVector = if (muted) Icons.Filled.MicOff else Icons.Filled.Mic,
                    contentDescription = if (muted) "Unmute microphone" else "Mute microphone"
                )
            }
        }

        FloatingActionButton(
            onClick = {
                if (isLive) {
                    onIntent(MainStreamIntent.StopStream)
                } else {
                    onIntent(MainStreamIntent.StartStream)
                }
            },
            containerColor = fabColor
        ) {
            Crossfade(
                targetState = isLive,
                animationSpec = tween(200),
                label = "stream"
            ) { live ->
                Icon(
                    imageVector = if (live) Icons.Filled.Stop else Icons.Filled.PlayArrow,
                    contentDescription = if (live) "Stop stream" else "Start stream"
                )
            }
        }

        IconButton(
            onClick = { onIntent(MainStreamIntent.SwitchCamera) },
            modifier = Modifier
                .clip(CircleShape)
                .background(MaterialTheme.colorScheme.surface.copy(alpha = 0.85f))
        ) {
            Crossfade(
                targetState = isFrontCamera,
                animationSpec = tween(200),
                label = "camera"
            ) { front ->
                Icon(
                    imageVector = if (front) Icons.Filled.CameraRear else Icons.Filled.CameraFront,
                    contentDescription = if (front) "Switch to back camera" else "Switch to front camera"
                )
            }
        }
    }
}

private fun statusColor(status: StreamStatus): Color = when (status) {
    StreamStatus.OFFLINE -> Color.Gray
    StreamStatus.CONNECTING -> Color(0xFFFFA000)
    StreamStatus.ONLINE -> Color(0xFF2E7D32)
    StreamStatus.RECONNECTING -> Color(0xFFFF6F00)
}

private fun formatDuration(seconds: Long): String {
    val hours = seconds / 3600
    val minutes = (seconds % 3600) / 60
    val remainingSeconds = seconds % 60
    return "%02d:%02d:%02d".format(hours, minutes, remainingSeconds)
}

package com.example.twitchtest.presentation.screens.mainstream

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.example.twitchtest.data.streaming.StreamManager
import com.example.twitchtest.domain.model.StreamStatus
import com.example.twitchtest.domain.usecase.GetStreamKeyUseCase
import dagger.hilt.android.lifecycle.HiltViewModel
import javax.inject.Inject
import kotlinx.coroutines.flow.MutableSharedFlow
import kotlinx.coroutines.flow.SharedFlow
import kotlinx.coroutines.flow.SharingStarted
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asSharedFlow
import kotlinx.coroutines.flow.combine
import kotlinx.coroutines.flow.launchIn
import kotlinx.coroutines.flow.onEach
import kotlinx.coroutines.flow.stateIn
import kotlinx.coroutines.launch

@HiltViewModel
class MainStreamViewModel @Inject constructor(
    private val streamManager: StreamManager,
    getStreamKeyUseCase: GetStreamKeyUseCase
) : ViewModel() {

    val state: StateFlow<MainStreamState> = combine(
        getStreamKeyUseCase(),
        streamManager.streamStatus,
        streamManager.streamDuration,
        streamManager.isMuted,
        streamManager.isFrontCamera
    ) { key, status, duration, muted, front ->
        MainStreamState(
            streamKey = key.orEmpty(),
            streamStatus = status,
            duration = duration,
            isMuted = muted,
            isFrontCamera = front
        )
    }.stateIn(
        viewModelScope,
        SharingStarted.WhileSubscribed(5000),
        MainStreamState()
    )

    private val _effect = MutableSharedFlow<MainStreamEffect>()
    val effect: SharedFlow<MainStreamEffect> = _effect.asSharedFlow()

    init {
        streamManager.errorMessage
            .onEach { message -> _effect.emit(MainStreamEffect.ShowError(message)) }
            .launchIn(viewModelScope)
    }

    fun onIntent(intent: MainStreamIntent) {
        when (intent) {
            is MainStreamIntent.InitializeStream -> streamManager.initialize(intent.openGlView)
            MainStreamIntent.StartPreview -> streamManager.startPreview()
            MainStreamIntent.StopPreview -> streamManager.stopPreview()
            is MainStreamIntent.SurfaceRecreated ->
                streamManager.onSurfaceRecreated(intent.openGlView)

            MainStreamIntent.StartStream -> startStream()
            MainStreamIntent.StopStream -> streamManager.stopStream()
            MainStreamIntent.ToggleMicrophone -> streamManager.toggleMicrophone()
            MainStreamIntent.SwitchCamera -> streamManager.switchCamera()
            MainStreamIntent.OpenViewerSheet -> {
                if (state.value.streamStatus == StreamStatus.ONLINE) {
                    viewModelScope.launch { _effect.emit(MainStreamEffect.ShowViewerSheet) }
                }
            }

            MainStreamIntent.CloseViewerSheet -> {
                viewModelScope.launch { _effect.emit(MainStreamEffect.HideViewerSheet) }
            }
        }
    }

    private fun startStream() {
        val key = state.value.streamKey.trim()
        if (key.isBlank()) return
        val rtmpUrl = "$TWITCH_RTMP_BASE_URL$key"
        streamManager.startStream(rtmpUrl)
    }

    override fun onCleared() {
        streamManager.release()
    }

    private companion object {
        const val TWITCH_RTMP_BASE_URL = "rtmp://live.twitch.tv/app/"
    }
}

