@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun ViewerListSheet(
    onDismiss: () -> Unit,
    viewModel: ViewerListViewModel = hiltViewModel()
) {
    val state by viewModel.state.collectAsStateWithLifecycle()

    ModalBottomSheet(onDismissRequest = onDismiss) {
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = 20.dp, vertical = 8.dp),
            verticalArrangement = Arrangement.spacedBy(12.dp)
        ) {
            Text(
                text = "Viewers (${state.viewers.size})",
                style = MaterialTheme.typography.headlineSmall
            )

            OutlinedTextField(
                value = state.searchQuery,
                onValueChange = { viewModel.onIntent(ViewerListIntent.Search(it)) },
                modifier = Modifier.fillMaxWidth(),
                label = { Text("Search viewers") },
                singleLine = true
            )

            if (state.isLoading && state.viewers.isEmpty()) {
                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(vertical = 32.dp),
                    contentAlignment = Alignment.Center
                ) {
                    CircularProgressIndicator()
                }
            } else {
                LazyColumn(
                    modifier = Modifier.fillMaxWidth()
                ) {
                    items(state.viewers, key = { it.id }) { user ->
                        ViewerItem(user = user)
                    }
                }
            }

            state.error?.let { error ->
                Text(
                    text = error,
                    color = MaterialTheme.colorScheme.error,
                    style = MaterialTheme.typography.bodyMedium,
                    modifier = Modifier.padding(bottom = 16.dp)
                )
            }
        }
    }
}

@Composable
private fun ViewerItem(user: User) {
    ListItem(
        headlineContent = {
            Text(
                text = user.fullName,
                fontWeight = FontWeight.SemiBold
            )
        },
        supportingContent = {
            Text(text = user.email)
        },
        leadingContent = {
            Box(
                modifier = Modifier
                    .size(40.dp)
                    .clip(CircleShape)
                    .background(MaterialTheme.colorScheme.primaryContainer),
                contentAlignment = Alignment.Center
            ) {
                Text(
                    text = user.firstName.firstOrNull()?.uppercase() ?: "?",
                    style = MaterialTheme.typography.titleMedium,
                    color = MaterialTheme.colorScheme.onPrimaryContainer
                )
            }
        }
    )
}

